#!/usr/bin/env python3
"""
Make /sys/einkinfo/dither_type reach the panel, by routing meink's hsm engine
through Bayer instead of Floyd-Steinberg.

Mudita compile all four dither algorithms into meink.ko and dispatch on the type
in three of their four engines. The engine this device runs, "hsm", calls
Floyd unconditionally from two helpers, so dither_type is stored, read back and
ignored. Floyd is error diffusion: the pattern re-flows whenever content shifts,
which is the crawling greys while scrolling. Bayer is ordered, so it holds still.

THE TRAP, which cost three black screens before it was found: meink has two
families of dither function with different conventions.

    ditherFloydSteinbergGrey_opt7_480_2(in, out, w, h, threshold)  5 args, out of place
    ditherBayerGreyNbpp(buf, w, h, levels)                         4 args, in place
    ditherAtkinsonGrey(buf, w, h, levels)                          4 args, in place

Floyd writes its result to arg2, the buffer at ctx+608 that hsmThreadedInit
allocates with chip_os_calloc(1, ctx+64). meink packs the frame from there.
Bayer writes in place to arg1 and never touches that buffer, so it stayed
calloc-zeroed and every frame went out as 48002 bytes of 0x00 -- solid black,
which an e-ink panel then retains through power-off and fastboot.

simpleThreaded_engine_thrd does dispatch to Bayer directly, but it pairs it with
ditherFloydSteinbergGrey_opt6_480, the 4-arg in-place variant. Copying that
argument setup into a 5-arg call site was the original mistake.

So the call sites are left byte-for-byte stock and only the relocation's symbol
index changes, pointing at a trampoline that bridges the conventions: copy the
frame into the output buffer, then dither it there in place.

The trampoline goes in ditherAtkinsonGrey. It is 412 bytes, has no internal
relocations to leave stale, and its only callers are the dispatchers of the
three engines that do not run on this device.

No new relocations are needed: the copy is an open-coded byte loop rather than a
call to memcpy (an undefined symbol), and the bl to Bayer is intra-.text so its
offset is encoded directly.

Usage: patch-meink-bayer.py <stock meink.ko> <output .ko>
"""
import struct
import sys

# The 5-arg call sites in the hsm helpers. Asserted, never modified.
SITES = {0x650C: "hsmThreadedPreProcessFrame", 0x6554: "hsmThreadedProcessDithering"}
SITE_WORDS = [0xF9413281, 0x29440E82, 0xB9403A84, 0xAA1303E0, 0x94000000]

SYM_FLOYD = 678  # ditherFloydSteinbergGrey_opt7_480_2, the 5-arg thunk
SYM_TRAMP = 674  # ditherAtkinsonGrey, whose body we replace
R_AARCH64_CALL26 = 0x11B

ADDR_TRAMP = 0x4A88  # ditherAtkinsonGrey
ADDR_BAYER = 0x49F8  # ditherBayerGreyNbpp
ATKINSON_FIRST = 0x1B017C49  # mul w9, w2, w1
ATKINSON_SIZE = 412

# BAYER_PATTERN_16X16, 256 int32 in .rodata. Replaced wholesale; see below.
ADDR_MATRIX = 0x6FAA50
MATRIX_FIRST = 0  # stock entry 0, the one that puts black dots on white

# A void-and-cluster blue-noise threshold matrix, replacing Mudita's Bayer.
#
# Two reasons. Bayer is perfectly periodic: at 50% grey every bit of its energy
# sits in one spatial frequency, which is the visible crosshatch. Blue noise
# spreads that over ~70 frequencies while staying position-only, so it keeps
# ordered dithering's stability -- the point of the exercise, since error
# diffusion is what crawls while scrolling.
#
# And the values are 1..255, never 0 or 256. The driver renders white iff
# matrix[x,y] + pixel >= 256, so a 0 entry puts a black dot on pure white
# (Mudita's matrix had exactly one, at index 0) and a 256 entry would put a
# white dot on pure black.
#
# Generated by vendor/tools/bluenoise.py, seed 20260922.
BLUE_NOISE_16X16 = [
     85, 145, 165, 229,  24, 141,  76, 178, 114,  46, 217,  27,  64, 153,  14, 210,
     45, 194,  70,  98, 214, 157, 197,  19, 243, 146,  94, 191, 249, 177, 233, 121,
    183, 237,  32, 130, 251,  63,   5, 103, 231, 167,  75,   1, 139,  81,  55,  20,
    218, 110,  11, 174,  43, 116, 208, 134,  37,  56, 128, 206, 115, 224, 100, 158,
    133,  79, 150, 204,  89, 186, 163,  83, 215, 182,  17, 238,  47,  33, 196,  66,
    169, 246,  57, 227,  18, 239,  51,  25, 247, 109,  90, 159, 173, 147, 254,   4,
     28,  97,  38, 126, 104, 140,  73, 151, 122, 192,  62, 221,  12,  86, 123, 213,
    113, 200, 180, 156,   1, 195, 219, 176,   7,  35, 138, 201, 105,  71, 187,  48,
    234,  68, 225,  78, 253,  59,  41,  96, 230,  77, 250,  49,  23, 241, 137, 161,
      8, 143,  22, 119, 166, 205, 132, 112, 207, 155, 168, 127, 179, 226,  36,  91,
    175, 102,  52, 188,  31,  84,  13, 245,  26,  67,  92,   2, 111, 149,  60, 209,
    129, 244, 216, 148, 236, 107, 162, 184, 144,  44, 235, 189, 212,  80,  21, 193,
     42,  82,  15,  65, 135, 211,  72,  54, 199, 118, 220,  30,  99, 164, 252, 117,
    222, 154, 181,  95,  40,   3, 232, 101,  16, 172, 136,  74,  53, 142,   6,  69,
     29, 108, 203, 248, 171, 190, 125, 152, 255,  87,  10, 240, 185, 228, 198, 170,
    242,  58,   9, 120,  50,  88, 223,  34,  61, 202, 160, 124, 106,  39,  93, 131,
]

# Assembled with aarch64-linux-android-as; see the .s in the commit message.
#   (x0=in, x1=out, w2=w, w3=h, w4=threshold)
#   copy w2*w3 bytes in->out, then ditherBayerGreyNbpp(out, w, h, 1)
# levels=1 gives step 256, so each pixel lands on 0 or 255 -- the same two-level
# output Floyd produces, which is what the packer downstream expects.
TRAMPOLINE = [
    0xA9BF7BFD,  # stp  x29, x30, [sp,#-16]!
    0x910003FD,  # mov  x29, sp
    0x1B037C45,  # mul  w5, w2, w3
    0x2A1F03E6,  # mov  w6, wzr
    0x6B0500DF,  # 1: cmp  w6, w5
    0x540000A2,  # b.hs 2f
    0x38664807,  # ldrb w7, [x0, w6, uxtw]
    0x38264827,  # strb w7, [x1, w6, uxtw]
    0x110004C6,  # add  w6, w6, #1
    0x17FFFFFB,  # b    1b
    0xAA0103E0,  # 2: mov  x0, x1
    0x2A0203E1,  # mov  w1, w2
    0x2A0303E2,  # mov  w2, w3
    0x52800023,  # mov  w3, #1
    0x94000000,  # bl   ditherBayerGreyNbpp   <- offset filled in below
    0xA8C17BFD,  # ldp  x29, x30, [sp],#16
    0xD65F03C0,  # ret
]
BL_INDEX = 14


def bl_word(pc, target):
    """R_AARCH64_CALL26 encoded directly: intra-.text, so no relocation needed."""
    off = (target - pc) >> 2
    if not -(1 << 25) <= off < (1 << 25):
        sys.exit("FAIL: bl out of range")
    return 0x94000000 | (off & 0x03FFFFFF)


def sections(blob):
    e_shoff, = struct.unpack_from("<Q", blob, 0x28)
    e_shentsize, e_shnum, e_shstrndx = struct.unpack_from("<HHH", blob, 0x3A)
    raw = []
    for i in range(e_shnum):
        off = e_shoff + i * e_shentsize
        name, _t, _f, _a, sh_off, size, _l, _i, _al, _es = \
            struct.unpack_from("<IIQQQQIIQQ", blob, off)
        raw.append((name, sh_off, size))
    stroff = raw[e_shstrndx][1]
    out = {}
    for name, sh_off, size in raw:
        end = blob.index(b"\0", stroff + name)
        out[blob[stroff + name:end].decode()] = (sh_off, size)
    return out


def main():
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    src, dst = sys.argv[1], sys.argv[2]
    stock = open(src, "rb").read()
    blob = bytearray(stock)
    sec = sections(blob)
    for need in (".text", ".rela.text", ".rodata"):
        if need not in sec:
            sys.exit("FAIL: no %s section" % need)
    text_off = sec[".text"][0]
    rodata_off = sec[".rodata"][0]
    rela_off, rela_size = sec[".rela.text"]

    # 1. call sites must be untouched stock -- we rely on their 5-arg setup
    for vaddr, fname in sorted(SITES.items()):
        got = list(struct.unpack_from("<5I", blob, text_off + vaddr))
        if got != SITE_WORDS:
            sys.exit("FAIL: %s at 0x%x is not stock\n  want %s\n  got  %s"
                     % (fname, vaddr, [hex(x) for x in SITE_WORDS],
                        [hex(x) for x in got]))
    print("call sites stock: %s" % ", ".join(sorted(SITES.values())))

    # 2. trampoline over ditherAtkinsonGrey
    base = text_off + ADDR_TRAMP
    first, = struct.unpack_from("<I", blob, base)
    if first != ATKINSON_FIRST:
        sys.exit("FAIL: ditherAtkinsonGrey is not stock (0x%08x), already patched?"
                 % first)
    if len(TRAMPOLINE) * 4 > ATKINSON_SIZE:
        sys.exit("FAIL: trampoline does not fit")
    words = list(TRAMPOLINE)
    words[BL_INDEX] = bl_word(ADDR_TRAMP + BL_INDEX * 4, ADDR_BAYER)
    struct.pack_into("<%dI" % len(words), blob, base, *words)
    print("trampoline at 0x%04x, %d instrs, bl -> 0x%04x"
          % (ADDR_TRAMP, len(words), ADDR_BAYER))

    # 3. repoint the two call relocations at the trampoline; offsets unchanged
    want = (SYM_FLOYD << 32) | R_AARCH64_CALL26
    new = (SYM_TRAMP << 32) | R_AARCH64_CALL26
    done = 0
    for i in range(rela_size // 24):
        ent = rela_off + i * 24
        r_offset, r_info, r_addend = struct.unpack_from("<QQq", blob, ent)
        if r_offset - 16 in SITES and r_info == want and r_addend == 0:
            struct.pack_into("<QQq", blob, ent, r_offset, new, 0)
            print("reloc 0x%04x  sym %d -> %d" % (r_offset, SYM_FLOYD, SYM_TRAMP))
            done += 1
    if done != len(SITES):
        sys.exit("FAIL: expected %d relocations, changed %d" % (len(SITES), done))

    # 4. threshold matrix: blue noise, and no 0 entry
    mbase = rodata_off + ADDR_MATRIX
    first, = struct.unpack_from("<i", blob, mbase)
    if first != MATRIX_FIRST:
        sys.exit("FAIL: threshold matrix is not stock (entry0=%d), already patched?"
                 % first)
    if len(BLUE_NOISE_16X16) != 256:
        sys.exit("FAIL: matrix must be 256 entries")
    if min(BLUE_NOISE_16X16) < 1 or max(BLUE_NOISE_16X16) > 255:
        sys.exit("FAIL: matrix must stay within 1..255")
    struct.pack_into("<256i", blob, mbase, *BLUE_NOISE_16X16)
    print("matrix at 0x%06x replaced: blue noise, range %d..%d"
          % (ADDR_MATRIX, min(BLUE_NOISE_16X16), max(BLUE_NOISE_16X16)))

    if len(blob) != len(stock):
        sys.exit("FAIL: size changed")
    diff = sum(1 for a, b in zip(stock, blob) if a != b)
    open(dst, "wb").write(blob)
    print("wrote %s  (%d bytes, %d differ)" % (dst, len(blob), diff))


if __name__ == "__main__":
    main()
